-- QODIQA PostgreSQL Migration 023
-- Fixes a type mismatch in migration 007 (consent_registry):
-- consent_audit_log.request_id was declared UUID, but every real caller
-- (src/api/routes/consent.js) passes req.requestId — generated by
-- middleware/requestId.js as `${Date.now()}-${randomBytes(4).toString('hex')}`,
-- never a UUID — causing every consent grant/revoke/suspend/resume call to
-- fail with "invalid input syntax for type uuid". Confirmed via the
-- acceptance test framework (AT-005) against a fresh, fully-migrated
-- Postgres instance.
--
-- VARCHAR(64) comfortably fits both the actual request-id format (~23
-- chars) and any genuine UUID (36 chars) that may already be stored, so
-- this is a widening, backward-compatible type change.
--
-- IDEMPOTENT: ALTER COLUMN TYPE is safe to re-run (no-op if already TEXT).

BEGIN;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'consent_audit_log' AND column_name = 'request_id' AND data_type = 'uuid'
  ) THEN
    ALTER TABLE consent_audit_log ALTER COLUMN request_id TYPE VARCHAR(64) USING request_id::text;
  END IF;
END
$$;

INSERT INTO qodiqa_migrations (version, name, checksum, applied_by)
VALUES (23, 'consent_audit_request_id_type_fix', 'PLACEHOLDER_CHECKSUM', current_user)
ON CONFLICT (version) DO NOTHING;

COMMIT;
